C[5] = dir(5*180/7);
C[6] = dir(6*180/7);

draw(A--B);
draw(arc((0,0),1,0,180));

for (i = 1; i <= 6; ++i) {
  draw(A--C[i]--B);
  dot("$C_" + string(i) + "$", C[i], C[i]);
